import { createGame, MOVES_MAX, ELAPSED_MAX_MS } from './game.ts';
import { parseBoardCode } from './deck.ts';
import {
  isJsonObject,
  isNonnegativeSafeInteger,
  isWithinBytes,
  parseJson,
} from './saved-format.ts';
import { readMatched, readSelection } from './snapshot-selection.ts';
import { SelectionKind } from './selection.ts';
import type { GameState } from './game.ts';

export const SNAPSHOT_VERSION = 1;
export const SNAPSHOT_MAX_BYTES = 65_536;
export const SNAPSHOT_KEYS = [
  'version',
  'boardCode',
  'matched',
  'selection',
  'moves',
  'elapsedMs',
  'started',
] as const;

export function encodeSnapshot(state: GameState): string {
  return JSON.stringify(
    {
      version: SNAPSHOT_VERSION,
      boardCode: state.boardCode,
      matched: [...state.matched].sort((left, right) => left - right),
      // Active time keeps its fractions in play. Export writes whole milliseconds, and rounding
      // pending time up keeps a mismatch at 1ms or more.
      selection:
        state.selection.kind === SelectionKind.mismatch
          ? { ...state.selection, remainingMs: Math.ceil(state.selection.remainingMs) }
          : state.selection,
      moves: state.moves,
      elapsedMs: Math.floor(state.elapsedMs),
      started: state.started,
    },
    null,
    2,
  );
}

export function decodeSnapshot(text: string): GameState | null {
  const value = isWithinBytes(text, SNAPSHOT_MAX_BYTES) ? parseJson(text) : undefined;
  if (
    !isJsonObject(value) ||
    !Object.keys(value).every((key, index) =>
      index === 0 ? key === SNAPSHOT_KEYS[0] : SNAPSHOT_KEYS.some((field) => field === key),
    ) ||
    Object.keys(value).length !== SNAPSHOT_KEYS.length ||
    value.version !== SNAPSHOT_VERSION
  )
    return null;
  if (typeof value.boardCode !== 'string' || !parseBoardCode(value.boardCode)) return null;
  if (
    !isNonnegativeSafeInteger(value.moves) ||
    value.moves > MOVES_MAX ||
    !isNonnegativeSafeInteger(value.elapsedMs) ||
    value.elapsedMs > ELAPSED_MAX_MS ||
    typeof value.started !== 'boolean'
  )
    return null;
  const initial = createGame(value.boardCode);
  const matched = readMatched(value.matched, initial);
  if (!matched) return null;
  const selection = readSelection(value.selection, initial, matched);
  if (!selection) return null;
  const state: GameState = {
    ...initial,
    matched,
    selection,
    moves: value.moves,
    elapsedMs: value.elapsedMs,
    started: value.started,
  };
  const minimumMoves = matched.length / 2 + (selection.kind === SelectionKind.mismatch ? 1 : 0);
  if (state.moves < minimumMoves) return null;
  if (
    !state.started &&
    (state.moves !== 0 ||
      state.elapsedMs !== 0 ||
      matched.length !== 0 ||
      selection.kind !== SelectionKind.closed)
  )
    return null;
  if (state.started && state.moves === 0 && selection.kind === SelectionKind.closed) return null;
  return state;
}
export function isJsonObject(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

export function isNonnegativeSafeInteger(value: unknown): value is number {
  return typeof value === 'number' && Number.isSafeInteger(value) && value >= 0;
}

export function hasExactKeys(value: Record<string, unknown>, keys: readonly string[]): boolean {
  return (
    Object.keys(value).length === keys.length && keys.every((key) => Object.hasOwn(value, key))
  );
}

export function isWithinBytes(text: string, maxBytes: number): boolean {
  return new TextEncoder().encode(text).byteLength <= maxBytes;
}

// No JSON text parses to undefined, so it marks malformed input.
export function parseJson(text: string): unknown {
  try {
    const value: unknown = JSON.parse(text);
    return value;
  } catch {
    return undefined;
  }
}
import { hasExactKeys, isJsonObject, isNonnegativeSafeInteger } from './saved-format.ts';
import { MISMATCH_MS } from './game.ts';
import { SelectionKind, type Selection } from './selection.ts';
import type { GameState } from './game.ts';

export function readSelection(
  value: unknown,
  state: GameState,
  matched: readonly number[],
): Selection | null {
  if (!isJsonObject(value)) return null;
  const available = (index: unknown): index is number =>
    isNonnegativeSafeInteger(index) && index < state.deck.length && !matched.includes(index);
  switch (value.kind) {
    case SelectionKind.closed:
      return hasExactKeys(value, ['kind']) ? { kind: SelectionKind.closed } : null;
    case SelectionKind.one:
      return hasExactKeys(value, ['kind', 'index']) && available(value.index)
        ? { kind: SelectionKind.one, index: value.index }
        : null;
    case SelectionKind.mismatch:
      if (!hasExactKeys(value, ['kind', 'first', 'second', 'remainingMs'])) return null;
      if (!available(value.first) || !available(value.second) || value.first === value.second)
        return null;
      if (state.deck[value.first] === state.deck[value.second]) return null;
      if (
        !isNonnegativeSafeInteger(value.remainingMs) ||
        value.remainingMs < 1 ||
        value.remainingMs > MISMATCH_MS
      )
        return null;
      return {
        kind: SelectionKind.mismatch,
        first: value.first,
        second: value.second,
        remainingMs: value.remainingMs,
      };
    default:
      return null;
  }
}

export function readMatched(value: unknown, state: GameState): readonly number[] | null {
  if (!Array.isArray(value)) return null;
  const matched: number[] = [];
  const counts = new Map<number, number>();
  for (const index of value) {
    if (!isNonnegativeSafeInteger(index) || index >= state.deck.length || matched.includes(index))
      return null;
    const face = state.deck[index];
    if (face === undefined) return null;
    matched.push(index);
    counts.set(face, (counts.get(face) ?? 0) + 1);
  }
  return [...counts.values()].every((count) => count === 2) ? matched : null;
}
