import assert from 'node:assert/strict';
import { test } from 'vitest';
import { activateCard, advanceGame, createGame } from './game.ts';
import { decodeSnapshot, encodeSnapshot } from './snapshot.ts';
import { isJsonObject } from './saved-format.ts';
import { EXAMPLE_CODE, EXAMPLE_PAIRS } from './game.fixture.ts';

const initial = createGame(EXAMPLE_CODE);
const oneRevealed = advanceGame(activateCard(initial, 0), 123);
const pendingMismatch = advanceGame(activateCard(oneRevealed, 1), 175);
const completed = EXAMPLE_PAIRS.reduce(
  (state, [first, second]) => activateCard(activateCard(state, first), second),
  initial,
);

test('snapshots preserve progress with version in the middle or last', () => {
  for (const state of [initial, oneRevealed, pendingMismatch, completed]) {
    const canonical = encodeSnapshot(state);
    const expected = decodeSnapshot(canonical);
    assert.ok(expected, 'the original export loads');
    const value: unknown = JSON.parse(canonical);
    assert.ok(isJsonObject(value));
    const entries = Object.entries(value);
    const orders = [
      [...entries].reverse(),
      [...entries.slice(3), ...entries.slice(0, 3)],
      [...entries].sort(([left], [right]) => left.localeCompare(right)),
    ];
    for (const order of orders) {
      const text = JSON.stringify(Object.fromEntries(order));
      const decoded = decodeSnapshot(text);
      assert.deepEqual(decoded, expected, 'property order does not change imported progress');
      assert.ok(decoded);
      assert.equal(encodeSnapshot(decoded), canonical, 'export retains its canonical format');
    }
  }
});

test('reordered snapshots still reject missing, unknown and invalid fields', () => {
  const value: unknown = JSON.parse(encodeSnapshot(pendingMismatch));
  assert.ok(isJsonObject(value));
  const missing = Object.fromEntries(Object.entries(value).filter(([key]) => key !== 'started'));
  const invalid = [
    missing,
    { ...value, extra: true },
    { ...value, version: 2 },
    { ...value, moves: -1 },
  ];
  for (const fields of invalid) {
    const text = JSON.stringify(Object.fromEntries(Object.entries(fields).reverse()));
    assert.equal(decodeSnapshot(text), null);
  }
});

import { useEffect, useRef } from 'react';
import { isWon } from '../game.ts';
import { SelectionKind } from '../selection.ts';
import { CLOCK_INTERVAL_MS, createClock, elapsedStep } from './browser-clock.ts';
import { tickSession } from './session.ts';
import type { RefObject } from 'react';
import type { Session } from './session.ts';

export function useSessionClock(
  session: Session,
  current: RefObject<Session>,
  commit: (next: Session) => void,
) {
  const clock = useRef(createClock(performance.now()));
  const visible = useRef(!document.hidden);
  const won = isWon(session.game);

  function running(): boolean {
    return (
      visible.current &&
      !current.current.paused &&
      current.current.game.started &&
      !isWon(current.current.game)
    );
  }

  function synchronize(generation = current.current.generation): void {
    if (generation !== current.current.generation) return;
    const now = performance.now();
    const step = elapsedStep(clock.current, now, running());
    clock.current = step.clock;
    if (step.milliseconds) commit(tickSession(current.current, generation, step.milliseconds));
  }

  useEffect(() => {
    const generation = session.generation;
    let active = true;
    let timer: number | undefined;
    function schedule(): void {
      window.clearTimeout(timer);
      if (!active || generation !== current.current.generation || !running()) return;
      const selection = current.current.game.selection;
      const delay =
        selection.kind === SelectionKind.mismatch
          ? Math.min(CLOCK_INTERVAL_MS, selection.remainingMs)
          : CLOCK_INTERVAL_MS;
      timer = window.setTimeout(() => {
        if (!active) return;
        synchronize(generation);
        schedule();
      }, delay);
    }
    function visibilityChanged(): void {
      if (!active || generation !== current.current.generation) return;
      synchronize(generation);
      visible.current = !document.hidden;
      schedule();
    }
    schedule();
    document.addEventListener('visibilitychange', visibilityChanged);
    return () => {
      active = false;
      window.clearTimeout(timer);
      document.removeEventListener('visibilitychange', visibilityChanged);
    };
  }, [session.generation, session.game.started, session.paused, won]);

  return {
    synchronize,
    reset: () => {
      clock.current = createClock(performance.now());
    },
  };
}
export const CLOCK_INTERVAL_MS = 40;

interface ActiveClock {
  readonly observedAt: number;
}

export function createClock(now: number): ActiveClock {
  return { observedAt: now };
}

// Fractions stay in the game, so a mismatch runs from its own activation and only exports round.
export function elapsedStep(clock: ActiveClock, now: number, active: boolean) {
  const delta = now - clock.observedAt;
  const milliseconds = active && Number.isFinite(delta) && delta > 0 ? delta : 0;
  return { clock: createClock(now), milliseconds };
}
import { useEffect } from 'react';
import { writePreferences } from './storage.ts';
import type { Preferences, PreferenceStore } from './storage.ts';

// Reading localStorage can throw when the browser blocks storage, and play continues without it.
export function browserStore(): PreferenceStore | null {
  try {
    return window.localStorage;
  } catch {
    return null;
  }
}

// Saves this tab's size and bests after each change.
export function useSavedPreferences(store: PreferenceStore | null, preferences: Preferences) {
  useEffect(() => {
    writePreferences(store, preferences);
  }, [preferences, store]);
}
