13	
14	export const SNAPSHOT_VERSION = 1;
15	export const SNAPSHOT_MAX_BYTES = 65_536;
16	export const SNAPSHOT_KEYS = [
17	  'version',
18	  'boardCode',
19	  'matched',
20	  'selection',
21	  'moves',
22	  'elapsedMs',
23	  'started',
24	] as const;
25	
26	export function encodeSnapshot(state: GameState): string {
27	  return JSON.stringify(
28	    {
29	      version: SNAPSHOT_VERSION,
30	      boardCode: state.boardCode,
31	      matched: [...state.matched].sort((left, right) => left - right),
32	      // Active time keeps its fractions in play. Export writes whole milliseconds, and rounding
33	      // pending time up keeps a mismatch at 1ms or more.
34	      selection:
35	        state.selection.kind === SelectionKind.mismatch
36	          ? { ...state.selection, remainingMs: Math.ceil(state.selection.remainingMs) }
37	          : state.selection,
38	      moves: state.moves,
39	      elapsedMs: Math.floor(state.elapsedMs),
40	      started: state.started,
41	      ...(state.name ? { name: state.name } : {}),
42	    },
43	    null,
44	    2,
45	  );
46	}
47	
48	export function decodeSnapshot(text: string): GameState | null {
49	  const value = isWithinBytes(text, SNAPSHOT_MAX_BYTES) ? parseJson(text) : undefined;
50	  if (
51	    !isJsonObject(value) ||
52	    !hasExactKeys(
53	      value,
54	      Object.hasOwn(value, 'name') ? [...SNAPSHOT_KEYS, 'name'] : SNAPSHOT_KEYS,
55	    ) ||
56	    value.version !== SNAPSHOT_VERSION
57	  )
58	    return null;
59	  if (
60	    Object.hasOwn(value, 'name') &&
61	    (typeof value.name !== 'string' || value.name.length > GAME_NAME_MAX_CHARACTERS)
62	  )
63	    return null;
64	  if (typeof value.boardCode !== 'string' || !parseBoardCode(value.boardCode)) return null;
65	  if (
66	    !isNonnegativeSafeInteger(value.moves) ||
67	    value.moves > MOVES_MAX ||
68	    !isNonnegativeSafeInteger(value.elapsedMs) ||
69	    value.elapsedMs > ELAPSED_MAX_MS ||
70	    typeof value.started !== 'boolean'
71	  )
72	    return null;
73	  const initial = createGame(value.boardCode);
74	  const matched = readMatched(value.matched, initial);
75	  if (!matched) return null;
76	  const selection = readSelection(value.selection, initial, matched);
77	  if (!selection) return null;
78	  const state: GameState = {
79	    ...initial,
80	    matched,
81	    selection,
82	    moves: value.moves,
83	    elapsedMs: value.elapsedMs,
84	    started: value.started,
85	    ...(typeof value.name === 'string' && value.name ? { name: value.name } : {}),
86	  };
87	  const minimumMoves = matched.length / 2 + (selection.kind === SelectionKind.mismatch ? 1 : 0);
88	  if (state.moves < minimumMoves) return null;
89	  if (
90	    !state.started &&
91	    (state.moves !== 0 ||
92	      state.elapsedMs !== 0 ||
93	      matched.length !== 0 ||
94	      selection.kind !== SelectionKind.closed)
95	  )
96	    return null;
97	  if (state.started && state.moves === 0 && selection.kind === SelectionKind.closed) return null;
98	  return state;
99	}
